{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have an aws_s3_bucket_public_access_block resource configured, leaving it potentially exposed to public access if bucket policies or ACLs are misconfigured."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "Server-side encryption is not explicitly configured. While AWS may apply default encryption, best practice requires explicit configuration of SSE-KMS or SSE-S3 via aws_s3_bucket_server_side_encryption_configuration."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the bucket. This prevents recovery from accidental deletions or overwrites and is a critical control for data integrity and availability."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "Access logging is not configured. Without logs, it is impossible to audit who accessed the bucket contents, which is essential for security monitoring and incident response."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "changeme_aws_s3_bucket_backend_simple" {
  force_destroy = true
  bucket        = "changeme-${random_id.changeme_backends_s3_bucket_name.hex}"
}

resource "aws_s3_bucket_public_access_block" "changeme_aws_s3_bucket_backend_simple" {
  bucket                  = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "changeme_aws_s3_bucket_backend_simple" {
  bucket        = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  target_bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  target_prefix = "log/"
}",
  "fix_summary": "Added aws_s3_bucket_public_access_block to prevent public exposure, aws_s3_bucket_server_side_encryption_configuration to enforce KMS encryption, aws_s3_bucket_versioning to enable data protection against accidental deletion, and aws_s3_bucket_logging to enable access auditing."
}
